ical-align:middle}.bar-track{display:inline-block;width:110px;height:7px;background:#e8eff1;vertical-align:middle}.bar-fill{display:block;height:7px;background:#075c7a}.bar-value{display:inline-block;width:20px;color:#294850;font-size:5.5px;font-weight:900;text-align:right}.register-table,.action-table{table-layout:fixed;page-break-inside:auto}.register-table thead,.action-table thead{display:table-header-group}.register-table tr,.action-table tr{page-break-inside:avoid}.register-table th,.action-table th{padding:4px 3px;border:1px solid #075c7a;background:#075c7a;color:#fff;font-size:5px;font-weight:900;text-align:left;text-transform:uppercase}.register-table td,.action-table td{padding:4px 3px;border:1px solid #d7e3e6;color:#294750;font-size:5.15px;overflow-wrap:anywhere;vertical-align:top}.register-table tbody tr:nth-child(even) td,.action-table tbody tr:nth-child(even) td{background:#f8fafb}.instrument-col{width:18%}.domain-col{width:16%}.account-col{width:16%}.risk-col{width:10%}.lifecycle-col{width:14%}.review-col{width:12%}.action-col{width:14%}.strong{color:#17343e;font-weight:900}.muted{display:block;margin-top:1px;color:#6b7e85;font-size:4.8px}.status{font-weight:900;text-transform:uppercase}.success{color:#176348}.warning{color:#8a5a13}.danger{color:#993f3d}.neutral{color:#61757c}.info{color:#17667e}.page-break{page-break-before:always}.detail-card{margin-top:7px;padding:7px;border:1px solid #cbdcdf;border-left:4px solid #075c7a;background:#f8fbfb;page-break-inside:avoid}.detail-title{font-size:7px;font-weight:900}.detail-subtitle{margin-top:2px;color:#657a81;font-size:5.4px}.detail-table{margin-top:5px}.detail-table td{width:25%;padding:4px 5px;border:1px solid #d7e3e6;vertical-align:top}.prose{margin-top:5px;padding:5px 6px;border:1px solid #d7e3e6;background:#fff;white-space:pre-line}.prose strong{display:block;margin-bottom:2px;color:#075c7a;font-size:5.4px;text-transform:uppercase}.empty{padding:18px!important;color:#647980!important;text-align:center}.footer{position:fixed;right:0;bottom:-32px;left:0;padding:6px 10px 5px;border-top:3px solid #77adba;background:#05465d;color:#d7ebef;font-size:5.8px}.footer-table td{width:33.333%;border:0;padding:0}.footer-brand{color:#fff;font-weight:900}.footer-context{color:#cde9ef;text-align:center}.footer-page{color:#fff;font-weight:800;text-align:right}.page-number:after{content:"Page " counter(page) " of " counter(pages)}
