@php
    $maxLifecycle = max(1, (int) collect($charts['lifecycle'])->max('count'));
    $maxDomain = max(1, (int) collect($charts['domain'])->max('controls'));
    $maxRisk = max(1, (int) collect($charts['risk'])->max('count'));
    $tone = fn ($value) => match ($value) {
        'approved', 'implemented', 'resolved', 'low', 'scheduled' => 'success',
        'under_review', 'in_progress', 'internal', 'public' => 'info',
        'draft', 'moderate', 'due_soon', 'risk_accepted', 'not_started' => 'warning',
        'critical', 'high', 'overdue', 'open', 'restricted' => 'danger',
        default => 'neutral',
    };
@endphp
<header class="header"><table class="header-table"><tr><td class="brand-cell"><span class="logo-wrap"><img src="{{ public_path('assets/images/attp-logo.jpeg') }}" alt="ATTP"></span></td><td><h1 class="title">ATTP Data Governance Framework</h1><div class="subtitle">Authority, stewardship, classification, risk, control implementation and remediation accountability</div></td><td class="header-side"><strong>{{ $isIndividual ? 'INDIVIDUAL CONTROL SHEET' : 'CONSOLIDATED GOVERNANCE REGISTER' }}</strong><br>Generated {{ $generatedAt->format('d M Y, H:i') }}<br>{{ $generatedAt->timezoneName }}</td></tr></table></header>

<section class="section"><div class="section-title">Report context and control</div><table class="meta-table"><tr><td><span class="meta-label">Reporting scope</span><span class="meta-value">{{ $scopeLabel }}</span></td><td><span class="meta-label">Prepared by</span><span class="meta-value">{{ $generatedBy->name }}</span><span class="muted">{{ $generatedBy->email }}</span></td><td><span class="meta-label">Register reference</span><span class="meta-value">ATTP-MEL-DG-{{ $generatedAt->format('Ymd-Hi') }}</span></td><td><span class="meta-label">Control principle</span><span class="meta-value">Approved versions are authoritative</span><span class="muted">Changes require a new controlled version</span></td></tr></table><div class="control-note"><strong>Governance interpretation:</strong> register presence does not prove implementation. Authority requires approval; operating effectiveness requires an implemented state, evidence, current review and closure of material actions.</div></section>

<section class="section"><div class="section-title">Executive governance posture</div><table class="summary-table"><tr><td><span class="summary-label">Active instruments</span><span class="summary-value">{{ number_format($metrics['active']) }}</span><span class="summary-meta">{{ number_format($metrics['controls']) }} records in scope</span></td><td><span class="summary-label">Approval rate</span><span class="summary-value">{{ number_format($metrics['approval_rate'], 1) }}%</span><span class="summary-meta">{{ number_format($metrics['approved']) }} authoritative</span></td><td><span class="summary-label">Implementation rate</span><span class="summary-value">{{ number_format($metrics['implementation_rate'], 1) }}%</span><span class="summary-meta">{{ number_format($metrics['implemented']) }} operating</span></td><td><span class="summary-label">Ownership coverage</span><span class="summary-value">{{ number_format($metrics['ownership_rate'], 1) }}%</span><span class="summary-meta">Owner and steward assigned</span></td><td><span class="summary-label">Overdue reviews</span><span class="summary-value">{{ number_format($metrics['overdue_reviews']) }}</span><span class="summary-meta">{{ number_format($metrics['due_soon']) }} due within 30 days</span></td><td><span class="summary-label">Open actions</span><span class="summary-value">{{ number_format($metrics['open_actions']) }}</span><span class="summary-meta">{{ number_format($metrics['critical_high']) }} high/critical instruments</span></td></tr></table></section>

<section class="section"><div class="section-title">Graphical posture profile</div><table class="visual-table"><tr>
    <td><div class="visual-title">Lifecycle authority</div>@forelse($charts['lifecycle'] as $row)<div class="bar-row"><span class="bar-label">{{ $row['label'] }}</span><span class="bar-track"><span class="bar-fill" style="width:{{ round(($row['count']/$maxLifecycle)*100,1) }}%;background:{{ $row['color'] }}"></span></span><span class="bar-value">{{ $row['count'] }}</span></div>@empty<span class="muted">No lifecycle data in scope.</span>@endforelse</td>
    <td><div class="visual-title">Governance domains</div>@forelse($charts['domain'] as $row)<div class="bar-row"><span class="bar-label">{{ $row['label'] }}</span><span class="bar-track"><span class="bar-fill" style="width:{{ round(($row['controls']/$maxDomain)*100,1) }}%"></span></span><span class="bar-value">{{ $row['controls'] }}</span></div>@empty<span class="muted">No domain coverage in scope.</span>@endforelse</td>
    <td><div class="visual-title">Risk exposure</div>@forelse($charts['risk'] as $row)<div class="bar-row"><span class="bar-label">{{ $row['label'] }}</span><span class="bar-track"><span class="bar-fill" style="width:{{ round(($row['count']/$maxRisk)*100,1) }}%;background:{{ $row['color'] }}"></span></span><span class="bar-value">{{ $row['count'] }}</span></div>@empty<span class="muted">No risk data in scope.</span>@endforelse</td>
</tr></table></section>

<section class="section"><div class="section-title">Controlled governance register</div><div class="section-note">Lifecycle, implementation, review and action status are reported separately to avoid representing an approved document as an operating and effective control.</div><table class="register-table"><thead><tr><th class="instrument-col">Instrument</th><th class="domain-col">Domain and scope</th><th class="account-col">Owner / steward</th><th class="risk-col">Risk / classification</th><th class="lifecycle-col">Lifecycle / implementation</th><th class="review-col">Effective / review</th><th class="action-col">Action posture</th></tr></thead><tbody>
