    <tr><td><span class="strong">{{ $control->control_code }} v{{ $control->version }}</span><span class="muted">{{ $control->title }}</span><span class="muted">{{ $instrumentTypes[$control->instrument_type] ?? str($control->instrument_type)->headline() }}</span></td><td><span class="strong">{{ $domains[$control->governance_domain] ?? str($control->governance_domain)->headline() }}</span><span class="muted">{{ $control->portfolio?->name ?: $control->thinkTank?->name ?: 'ATTP enterprise' }}</span></td><td><span class="strong">{{ $control->owner?->name ?: 'OWNER REQUIRED' }}</span><span class="muted">Steward: {{ $control->steward?->name ?: 'Not assigned' }}</span></td><td><span class="status {{ $tone($control->risk_rating) }}">{{ $risks[$control->risk_rating] ?? str($control->risk_rating)->headline() }}</span><span class="muted">{{ $classifications[$control->data_classification] ?? str($control->data_classification)->headline() }}</span></td><td><span class="status {{ $tone($control->status) }}">{{ $statuses[$control->status] ?? str($control->status)->headline() }}</span><span class="muted">{{ $implementationStatuses[$control->implementation_status] ?? str($control->implementation_status)->headline() }}</span></td><td><span class="strong">{{ $control->effective_date?->format('d M Y') ?: 'Not effective' }}</span><span class="status {{ $tone($reviewState) }}">{{ str($reviewState)->replace('_',' ')->headline() }}</span><span class="muted">{{ $control->next_review_date?->format('d M Y') ?: 'Not scheduled' }}</span></td><td><span class="strong">{{ $control->open_actions_count }} open / {{ $control->overdue_actions_count }} overdue</span><span class="muted">Evidence: {{ $control->evidence?->title ?: 'Not linked' }}</span></td></tr>
@empty<tr><td class="empty" colspan="7">No governance instruments match the selected scope.</td></tr>@endforelse
</tbody></table></section>

